public class JsLogger {
    private static final Log logger = LogFactory.getLog(JsLogger.class);

    public void log(Object... values) {
        if (values != null) {
            if (values.length <= 0) {
                logger.debug("");
            } else if (values.length == 1) {
                logger.debug(String.valueOf(values[0]));
