package org.wso2.carbon.identity.application.authentication.framework.config.model.graph.js;

import jdk.nashorn.api.scripting.AbstractJSObject;
import org.wso2.carbon.identity.application.common.model.ClaimMapping;

import java.util.Map;

/**
 * Javascript array like wrapper for a claim map of the authentication subject.
 * This provides array like access to the claim values keyed by a claim URI (local or remote).
 * e.g
 * var email = context.subject.claims.local["http://wso2.org/claims/emailaddress"]
 * <p>
 * The way a claim URI is derived from a {@link ClaimMapping} is delegated to the provided {@link IdMapper}, so that
 * the same view can be used to expose either the local or the remote claim URIs of the wrapped map.
 *
 * @see ClaimMapping
 */
public class JsClaimView extends AbstractJSObject {

    private final Map<ClaimMapping, String> claims;
    private final IdMapper idMapper;

    public JsClaimView(Map<ClaimMapping, String> claims, IdMapper idMapper) {

        this.claims = claims;
        this.idMapper = idMapper;
    }

    @Override
    public Object getMember(String name) {

        for (Map.Entry<ClaimMapping, String> entry : claims.entrySet()) {
            if (name.equals(idMapper.toId(entry.getKey()))) {
                return entry.getValue();
            }
        }
        return null;
    }

    @Override
    public void setMember(String name, Object value) {

        for (Map.Entry<ClaimMapping, String> entry : claims.entrySet()) {
            if (name.equals(idMapper.toId(entry.getKey()))) {
                entry.setValue(String.valueOf(value));
                return;
            }
        }
    }

    @Override
    public boolean isArray() {

        return true;
    }

    /**
     * Resolves the claim URI to be used as the key for a given {@link ClaimMapping}.
     */
    public interface IdMapper {

        /**
         * Extract the claim URI from the given claim mapping.
         *
         * @param claimMapping The claim mapping.
         * @return The claim URI to be used as the key.
         */
        String toId(ClaimMapping claimMapping);
    }
}
