package org.wso2.carbon.identity.application.authentication.framework.config.model.graph.js;

import org.wso2.carbon.identity.application.authentication.framework.util.FrameworkConstants;
import org.wso2.carbon.identity.application.common.model.ClaimMapping;

import java.util.Map;
import java.util.function.Consumer;

/**
 * Javascript wrapper for the claim set (user attributes) of the authentication subject.
 * This provides controlled access to the {@code Map<ClaimMapping, String>} of user attributes via provided javascript
 * native syntax.
 * e.g
 * var email = context.subject.claims.local["http://wso2.org/claims/emailaddress"]
 * context.subject.claims.push({local: "...", remote: "...", value: "..."})
 * <p>
 * Any change done through this wrapper is reflected on the wrapped user attributes map, hence persisting after the
 * authentication flow completes.
 *
 * @see ClaimMapping
 * @see JsClaimView
 */
public class JsClaimSet extends AbstractJSObjectWrapper<Map<ClaimMapping, String>> {

    private static final JsLogger LOG = JsLogger.getInstance();

    public JsClaimSet(Map<ClaimMapping, String> wrapped) {

        super(wrapped);
    }

    @Override
    public Object getMember(String name) {

        switch (name) {
            case FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_LOCAL:
                return new JsClaimView(getWrapped(),
                        claimMapping -> claimMapping.getLocalClaim().getClaimUri());
            case FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_REMOTE:
                return new JsClaimView(getWrapped(),
                        claimMapping -> claimMapping.getRemoteClaim().getClaimUri());
            case FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_PUSH:
                return (Consumer<Map>) this::push;
            default:
                return super.getMember(name);
        }
    }

    @Override
    public boolean hasMember(String name) {

        switch (name) {
            case FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_LOCAL:
            case FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_REMOTE:
            case FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_PUSH:
                return true;
            default:
                return super.hasMember(name);
        }
    }

    /**
     * Pushes a new claim to the wrapped user attributes map.
     * The provided claim object is expected to contain {@code local}, {@code remote} and {@code value} fields. If any
     * of those is missing, no entry is added to the map.
     *
     * @param claim The claim object provided from the javascript side.
     */
    public void push(Map claim) {

        if (claim == null) {
            LOG.error("Claim object provided to push is null.");
            return;
        }

        Object localClaimUri = claim.get(FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_LOCAL);
        Object remoteClaimUri = claim.get(FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_REMOTE);
        Object value = claim.get(FrameworkConstants.JSAttributes.JS_CLAIM_MEMBER_VALUE);

        if (localClaimUri == null || remoteClaimUri == null || value == null) {
            LOG.error("Malformed claim object provided to push. A claim requires local, remote and value fields.");
            return;
        }

        ClaimMapping claimMapping = ClaimMapping.build(String.valueOf(localClaimUri),
                String.valueOf(remoteClaimUri), null, false);
        getWrapped().put(claimMapping, String.valueOf(value));
    }

    /**
     * Whether the wrapped user attributes map is empty.
     *
     * @return true if there are no claims.
     */
    public boolean isEmpty() {

        return getWrapped().isEmpty();
    }
}
